<?php
session_start();require_once('check-login.php');require_once('website-content-utils.php');if(!isset($_SESSION['ACCESSLEVEL'])||$_SESSION['ACCESSLEVEL']!=='administrator'){http_response_code(403);exit('Administrator access required.');}aps_website_ensure($con);if(empty($_SESSION['aps_announcement_csrf']))$_SESSION['aps_announcement_csrf']=bin2hex(random_bytes(32));$message='';if(isset($_POST['publish'])&&hash_equals($_SESSION['aps_announcement_csrf'],$_POST['csrf']??'')){$title=trim((string)$_POST['title']);$text=trim((string)$_POST['announcement_text']);if($title!==''&&$text!==''){$stmt=mysqli_prepare($con,'INSERT INTO tblwebsiteannouncements(title,announcement_text,published_by) VALUES(?,?,?)');$user=$_SESSION['USERID'];mysqli_stmt_bind_param($stmt,'sss',$title,$text,$user);mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);$message='Announcement published.';}}if(isset($_POST['hide'])&&hash_equals($_SESSION['aps_announcement_csrf'],$_POST['csrf']??'')){mysqli_query($con,'UPDATE tblwebsiteannouncements SET status="hidden" WHERE announcement_id='.(int)$_POST['id']);}$rows=mysqli_query($con,'SELECT * FROM tblwebsiteannouncements ORDER BY published_at DESC');
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Announcements</title><style>body{margin:0;background:#f3f7fa;font:15px Arial;color:#183650}.wrap{max-width:900px;margin:35px auto;padding:0 18px}.card{background:#fff;border:1px solid #d7e2ea;border-radius:14px;padding:24px;margin-top:18px}label{display:block;font-weight:bold;margin:12px 0 6px}input,textarea{box-sizing:border-box;width:100%;padding:11px;border:1px solid #c8d6e2;border-radius:8px;font:inherit}textarea{min-height:120px}button,a{display:inline-block;padding:10px 13px;border:0;border-radius:8px;background:#08766f;color:#fff;text-decoration:none;font-weight:bold}.entry{border-top:1px solid #dce5eb;padding:14px 0}.entry p{white-space:pre-line}.msg{padding:12px;background:#e6f7ef;color:#126443;border-radius:8px}</style></head><body><main class="wrap"><a href="website-editor.php">← Website editor</a><section class="card"><h1>Publish announcement</h1><?php if($message){?><p class="msg"><?php echo aps_website_escape($message);?></p><?php }?><form method="post"><input type="hidden" name="csrf" value="<?php echo aps_website_escape($_SESSION['aps_announcement_csrf']);?>"><label>Title<input name="title" maxlength="180" required></label><label>Announcement<textarea name="announcement_text" maxlength="5000" required></textarea></label><button name="publish">Publish</button></form></section><section class="card"><h2>Announcement archive</h2><?php while($rows&&($row=mysqli_fetch_assoc($rows))){?><article class="entry"><b><?php echo aps_website_escape($row['title']);?></b> — <?php echo aps_website_escape($row['status']);?><p><?php echo aps_website_escape($row['announcement_text']);?></p><?php if($row['status']==='published'){?><form method="post"><input type="hidden" name="csrf" value="<?php echo aps_website_escape($_SESSION['aps_announcement_csrf']);?>"><input type="hidden" name="id" value="<?php echo (int)$row['announcement_id'];?>"><button name="hide">Hide</button></form><?php }?></article><?php }?></section></main></body></html>
